import{_ as t,c as a,o as n,ag as s}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Architecture","description":"How OIE is structured internally","frontmatter":{"title":"Architecture","description":"How OIE is structured internally"},"headers":[],"relativePath":"engine/architecture_overview.md","filePath":"engine/architecture_overview.md","lastUpdated":1788476353000}'),r={name:"engine/architecture_overview.md"};function o(i,e,l,c,d,h){return n(),a("div",null,e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>The Open Integration Engine (OIE) is an open source standards-based healthcare integration engine that enables interoperability between two systems by accepting incoming information packets, called messages, and processing them according to rules you provide. It speeds message routing, filtering, and transformation between health-info systems using various message formats (e.g., HL7, X12, EDI, DICOM, XML).</p><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><h3 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h3><p>Channels are the fundamental building blocks of OIE. A channel is an interface you configure to receive data from a source, take actions on that data (filter, transform, extract), and send it out to one or more destinations.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────┐    ┌─────────────────────────────────────────┐    ┌─────────────────┐</span></span>
<span class="line"><span>│  Source   │───&gt;│            OIE Channel                  │───&gt;│  Destination     │</span></span>
<span class="line"><span>│  System   │    │  Source Connector → Filter/Transformer  │    │  System(s)       │</span></span>
<span class="line"><span>└──────────┘    │               → Destination Connector(s) │    └─────────────────┘</span></span>
<span class="line"><span>                └─────────────────────────────────────────┘</span></span></code></pre></div><p>Each channel has general properties including a unique ID, name, and description. Channels can also be configured with code template library links, library resources, deploy/start dependencies (to control deployment order), attachment handler settings, message storage and pruning settings, and custom metadata columns.</p><h3 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h3><p>A channel consists of multiple <strong>connectors</strong>:</p><ul><li><strong>Source Connector</strong>. Gets data into OIE from an external system. Every channel has exactly one source connector. Source connectors may also include a <strong>source queue</strong> (when ON, messages are queued and a response is sent immediately before processing completes), a <strong>batch processor</strong> (to split incoming data into multiple messages), a <strong>response selector</strong> (to choose which response to return), and a <strong>max processing threads</strong> setting (to control concurrent processing).</li><li><strong>Destination Connectors</strong>. Sends data out to external systems. A channel has at least one, and may have multiple destination connectors. Each destination has an <strong>enabled</strong> flag and a <strong>wait for previous destination</strong> setting that determines its chain membership. Destinations also include a <strong>response transformer</strong> for processing responses received from external systems.</li></ul><p>For example, you may receive data over HTTP, then write it out to a file <strong>and</strong> insert pieces of it into a database.</p><p>See <a href="./channels_and_connectors.html">Channels and Connectors</a> and <a href="./connector_reference.html">Connector Reference</a> for details.</p><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p>A filter decides whether a message should proceed to the next step or not. A filter returns <strong>true</strong> (accepted) or <strong>false</strong> (filtered). Filters are comprised of multiple <strong>rules</strong>, joined by <strong>AND</strong> or <strong>OR</strong> operators.</p><ul><li>If the source connector filters out a message, it will not be processed by any destination connectors.</li><li>If a destination connector filters out a message, other destinations may still process it.</li></ul><p>See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h3 id="transformers" tabindex="-1">Transformers <a class="header-anchor" href="#transformers" aria-label="Permalink to &quot;Transformers&quot;">​</a></h3><p>A transformer modifies a message, converts it from one format to another, and extracts pieces for later use. A transformer has an <strong>inbound data type</strong> and an <strong>outbound data type</strong> (e.g., HL7 v2.x to JSON). Transformers are comprised of multiple <strong>steps</strong>, each of which modifies or extracts data.</p><p>See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h3 id="data-types" tabindex="-1">Data types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data types&quot;">​</a></h3><p>A data type tells a filter/transformer how to parse a certain format. The <strong>inbound</strong> data type <strong>serializes</strong> raw data into an internal representation that filters and transformers can work with. The <strong>outbound</strong> data type <strong>deserializes</strong> transformed data back into the actual outbound format.</p><p>The internal representation varies by data type. For example, HL7 v2.x data is serialized into an E4X XML object, JSON data becomes a JavaScript Object, and Raw data remains a Java String with no serialization.</p><p>Supported data types include:</p><ul><li>Delimited Text</li><li>DICOM</li><li>EDI / X12</li><li>HL7 v2.x</li><li>HL7 v3.x</li><li>JSON</li><li>NCPDP</li><li>Raw</li><li>XML</li></ul><p>See <a href="./data_types_and_formats.html">Data Types and Formats</a> for details.</p><h2 id="how-a-message-moves" tabindex="-1">How a message moves <a class="header-anchor" href="#how-a-message-moves" aria-label="Permalink to &quot;How a message moves&quot;">​</a></h2><p>A message enters through the source connector, passes the source filter and transformer, is handed to each destination chain, and produces a response for the sender. Four pages explain the mechanisms behind that sentence:</p><ul><li><a href="./message_lifecycle.html">Message Lifecycle and Storage</a>, the processing path, statuses, content types, and what each storage mode keeps</li><li><a href="./queueing.html">Queueing</a>, the source queue and destination queues</li><li><a href="./threading_and_ordering.html">Threading and Ordering</a>, which thread does the work, chains, and response selection</li><li><a href="./channel_state.html">Deploy, Start, and Channel State</a>, what deploy does and what each state means</li></ul><h2 id="channel-scripts" tabindex="-1">Channel scripts <a class="header-anchor" href="#channel-scripts" aria-label="Permalink to &quot;Channel scripts&quot;">​</a></h2><p>Four special scripts are associated with each channel:</p><ul><li><strong>Deploy Script</strong>. Runs once right before a channel is deployed.</li><li><strong>Preprocessor Script</strong>. Runs once for every message, after the attachment handler has optionally extracted data, but before the source filter/transformer. Used to modify the incoming message.</li><li><strong>Post Processor Script</strong>. Runs once for every message, after the source connector and all destinations have completed (excluding asynchronous processes like the destination queue), but before a response is sent back to the originating system. Has access to responses from all executed destinations and can return a custom response for the source connector to use.</li><li><strong>Undeploy Script</strong>. Runs once right before a channel is undeployed.</li></ul><h2 id="administration-interfaces" tabindex="-1">Administration interfaces <a class="header-anchor" href="#administration-interfaces" aria-label="Permalink to &quot;Administration interfaces&quot;">​</a></h2><ul><li><strong>Administrator</strong>. A Java Swing desktop client for managing channels, viewing messages, configuring settings, and monitoring the system. Connects to the server over HTTPS using a RESTful API. Requires a compatible launcher; see <a href="./desktop_administrator.html">Desktop Administrator</a> for the available options.</li><li><strong><a href="./web_administrator.html">Web Administrator</a></strong>. A browser-based administrator installed as the Web Support extension and served by the engine&#39;s own embedded Jetty. Read/write against the same REST API, so it and the desktop client can be used against one engine at the same time. Requires 4.6.0.</li><li><strong>Command Line Interface (CLI)</strong>. A terminal-based client for scripting and headless administration. Uses the same REST API as the Administrator.</li></ul><h2 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h2><p>OIE uses a plugin architecture where connectors, data types, and other features are loaded as extensions. Extension types include:</p><ul><li><strong>Connectors</strong>. Source and destination communication protocols</li><li><strong>Data Type Plugins</strong>. Message format parsers and serializers</li><li><strong>Server Plugins</strong>. Background services and event handlers</li><li><strong>Transmission Mode Providers</strong>. Frame-level protocol handling (e.g., MLLP)</li></ul><p>Extensions are discovered at runtime, so one install serves both the desktop and web administrators. A growing set of open source extensions is available beyond those bundled with the engine. See <a href="./extension_catalog.html">Plugins and Extensions</a>.</p>`,37)]))}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
